//! Character-data edits preserve passive host identity and actual native records.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-data.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn noscript_character_data_exact_units_properties_splices_ranges_and_actual_old_values(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),text=host.firstChild,watch=new MutationObserver(function(){});watch.observe(host,{childList:true,characterData:true,characterDataOldValue:true,subtree:true});function record(old){var rs=watch.takeRecords();if(rs.length!==1||rs[0].type!=='characterData'||rs[0].target!==text||rs[0].oldValue!==old||rs[0].addedNodes.length||rs[0].removedNodes.length||host.firstChild!==text||text.parentNode!==host||text.ownerDocument!==document)throw 'actual character record and identity';}var raw='\udfff\ud800<img id=fake src=missing><script>window.bad=1;</script>&amp;';text.data=raw;record('held');if(text.data!==raw||host.textContent!==raw||host.innerHTML!==raw||text.data.charCodeAt(0)!==57343||text.data.charCodeAt(1)!==55296)throw 'exact passive raw units';text.nodeValue=null;record(raw);if(text.data!==''||host.childNodes.length!==1)throw 'nullable nodeValue retains actual empty Text';text.textContent='ABCD';record('');var range=document.createRange();range.setStart(text,1);range.setEnd(text,3);text.insertData(1,'ZZ');record('ABCD');if(text.data!=='AZZBCD'||range.startOffset!==1||range.endOffset!==5)throw 'insertion moves following range boundary';text.deleteData(2,2);record('AZZBCD');if(text.data!=='AZCD'||range.startOffset!==1||range.endOffset!==3)throw 'deletion adjusts actual range';text.replaceData(0,2,'Q');record('AZCD');if(text.data!=='QCD'||range.startOffset!==0||range.endOffset!==2)throw 'replace adjusts actual range';text.appendData(raw);record('QCD');if(text.data!=='QCD'+raw||range.startContainer!==text||range.endContainer!==text||document.getElementById('fake')!==null||window.bad!==undefined||document.querySelectorAll('script').length)throw 'character edit stays passive';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_character_data_native_ancestor_and_other_interior_guards_refuse_atomically(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var guarded=document.getElementById('guard').firstChild,host=document.getElementById('host'),blocker=document.createTextNode('blocked'),watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let values=f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>();
 for code in ["guarded.data='blocked';","guarded.replaceData(0,1,'blocked');","host.appendChild(blocker);","guarded.parentNode.innerHTML='<b>blocked</b>'; "]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("inert resource subtrees"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>(),values);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||blocker.parentNode!==null||guarded.data!=='guarded')throw 'protected contents unchanged';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_character_data_quota_refusals_preserve_text_range_records_then_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),text=host.firstChild,range=document.createRange(),watch=new MutationObserver(function(){});range.setStart(text,1);range.setEnd(text,3);watch.observe(host,{characterData:true,characterDataOldValue:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=p.runtime.execute("text.replaceData(1,2,'expanded replacement');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();let e=e.to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==text||text.data!=='held'||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==3||watch.takeRecords().length)throw 'character refusal atomic';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"text.replaceData(1,2,'XYZ');var rs=watch.takeRecords();if(host.firstChild!==text||text.data!=='hXYZd'||range.startOffset!==1||range.endOffset!==1||rs.length!==1||rs[0].target!==text||rs[0].oldValue!=='held')throw 'fresh character recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
